#include <iostream>
#include <vector>
using namespace std;
const int BITS = 30;
struct TrieNode { int ch[2] = {-1,-1}; };
vector<TrieNode> trie;
void insert(int x) {
    int cur = 0;
    for (int i = BITS; i >= 0; i--) {
        int bit = (x >> i) & 1;
        if (trie[cur].ch[bit] == -1) { trie.push_back({}); trie[cur].ch[bit] = trie.size()-1; }
        cur = trie[cur].ch[bit];
    }
}
int maxXor(int x) {
    int cur = 0, res = 0;
    for (int i = BITS; i >= 0; i--) {
        int bit = (x >> i) & 1, want = 1 - bit;
        if (trie[cur].ch[want] != -1) { res |= (1 << i); cur = trie[cur].ch[want]; }
        else cur = trie[cur].ch[bit];
    }
    return res;
}
int main() {
    int n; cin >> n;
    vector<int> a(n);
    for (int i = 0; i < n; i++) cin >> a[i];
    trie.push_back({});
    for (int x : a) insert(x);
    int ans = 0;
    for (int x : a) ans = max(ans, maxXor(x));
    cout << ans << "\n";
    return 0;
}

