import java.util.*;
public class Main {
    static int[][] trie = new int[3200000][2];
    static int sz = 1;
    static { for(int[] r:trie) Arrays.fill(r,-1); }
    static void insert(int x) {
        int cur=0;
        for(int i=30;i>=0;i--){
            int b=(x>>i)&1;
            if(trie[cur][b]==-1){trie[cur][b]=sz++;}
            cur=trie[cur][b];
        }
    }
    static int maxXor(int x){
        int cur=0,res=0;
        for(int i=30;i>=0;i--){
            int b=(x>>i)&1, w=1-b;
            if(trie[cur][w]!=-1){res|=(1<<i);cur=trie[cur][w];}
            else cur=trie[cur][b];
        }
        return res;
    }
    public static void main(String[] args){
        Scanner sc=new Scanner(System.in);
        int n=sc.nextInt();
        int[] a=new int[n];
        for(int i=0;i<n;i++){a[i]=sc.nextInt();insert(a[i]);}
        int ans=0;
        for(int x:a) ans=Math.max(ans,maxXor(x));
        System.out.println(ans);
    }
}
